function [tau] = mtq_lovera(q, w, q_ref, w_ref, j, eps, kp, kv)
%MTQ_LOVERA  P1 Lovera & Astolfi 2004: u = -(eps^2 k_p q_v + eps k_v J w_e).
%   q: real[1][4] (passed a plain number)
%   w: real[1][3] (passed a plain number)
%   q_ref: real[1][4] (passed a plain number)
%   w_ref: real[1][3] (passed a plain number)
%   j: real[1][3][3] (passed a plain number)
%   eps: real[1] (passed a plain number)
%   kp: real[1] (passed a plain number)
%   kv: real[1] (passed a plain number)
%   returns tau: real[1][3] (passed a plain number)
%   Generated by tools/pcode.py from the pseudocode (trinetra-pcode/2); do not edit.
    tau = zeros(3, 1);
    [qe, s, wr, we] = asils.alg.control.mtq_err(q, w, q_ref, w_ref);
    jw = [j(1, 1)*we(1) + j(1, 2)*we(2) + j(1, 3)*we(3); j(2, 1)*we(1) + j(2, 2)*we(2) + j(2, 3)*we(3); j(3, 1)*we(1) + j(3, 2)*we(2) + j(3, 3)*we(3)];
    i = ((0):((3) - 1)).';
    tau((i) + 1) = (-(((((eps * eps) * kp) .* (s .* reshape(qe((i) + 1), [], 1))) + ((eps * kv) .* reshape(jw((i) + 1), [], 1)))));
end
